import Foundation

/// Recognizes only the direct helper layout generated by Nokcandu. Never uses app names.
public enum PadApplicationTarget {
    public static func helperHost(_ application: URL) -> URL? {
        let app = application.standardizedFileURL
        guard app.pathExtension.lowercased() == "app" else { return nil }
        let gameApp = app.deletingLastPathComponent()
        let shared = gameApp.deletingLastPathComponent()
        let contents = shared.deletingLastPathComponent()
        let host = contents.deletingLastPathComponent()
        guard gameApp.lastPathComponent == "GameApp", shared.lastPathComponent == "SharedSupport",
              contents.lastPathComponent == "Contents", host.pathExtension.lowercased() == "app" else { return nil }
        return host
    }
    public static func mode(bundleID: String?, application: URL?, modes: [String: String],
                            selectedPaths: [String: String]) -> PadCapturePolicy.Mode {
        // An explicit child rule, including Disabled, wins over its parent's rule.
        if let id = bundleID, let raw = modes[id] { return .init(rawValue: raw) ?? .disabled }
        guard let application, let host = helperHost(application.resolvingSymlinksInPath()) else { return .disabled }
        for id in selectedPaths.keys.sorted() {
            guard let raw = modes[id], let path = selectedPaths[id],
                  URL(fileURLWithPath: path).resolvingSymlinksInPath().standardizedFileURL.path == host.path else { continue }
            return .init(rawValue: raw) ?? .disabled
        }
        return .disabled
    }
}
